-- QUREO local knowledge v2: 51 original learning notes and Arabic-aware retrieval.
create or replace function public.x1_normalize_ai_text(p_value text)
returns text language sql immutable parallel safe set search_path=public as $$
 select trim(regexp_replace(translate(regexp_replace(lower(coalesce(p_value,'')), '[ًٌٍَُِّْـٰ]', '', 'g'),'أإآٱىة','اااايه'),'[^[:alnum:]ء-ي]+',' ','g'));
$$;
revoke all on function public.x1_normalize_ai_text(text) from public,anon,authenticated;
grant execute on function public.x1_normalize_ai_text(text) to service_role;
create or replace function public.x1_search_ai_knowledge(p_query text,p_agent text default 'qureo',p_limit integer default 8)
returns table(id uuid,slug text,category text,title text,content text,keywords text[],source_label text,relevance real)
language sql stable security invoker set search_path=public as $$
 with q as(select public.x1_normalize_ai_text(left(coalesce(p_query,''),500)) phrase),
 tokens as(select distinct token from q,unnest(string_to_array(q.phrase,' ')) token where length(token)>1 and token not in
 ('من','في','على','الى','الي','عن','مع','ده','دي','دا','انا','انت','هو','هي','هم','احنا','انتوا','عايز','عاوزه','ممكن','ازاي','كيف','فين','اين','افتح','لي','لو','ما','ماذا','هل','the','and','for','with','what','how','is','are','to','of')),
 ranked as(select k.*,(case when public.x1_normalize_ai_text(k.title)=q.phrase and q.phrase<>'' then 15 else 0 end
 +case when q.phrase<>'' and public.x1_normalize_ai_text(k.title) like '%'||q.phrase||'%' then 8 else 0 end
 +case when q.phrase<>'' and public.x1_normalize_ai_text(k.content) like '%'||q.phrase||'%' then 2 else 0 end
 +coalesce((select sum(case when public.x1_normalize_ai_text(k.title) like '%'||t.token||'%' then 4
 when exists(select 1 from unnest(k.keywords) kw where public.x1_normalize_ai_text(kw) like '%'||t.token||'%') then 3
 when public.x1_normalize_ai_text(k.category) like '%'||t.token||'%' then 2
 when public.x1_normalize_ai_text(k.content) like '%'||t.token||'%' then 1 else 0 end) from tokens t),0)
 +coalesce(ts_rank(k.search_vector,plainto_tsquery('simple',coalesce(p_query,''))),0)*1.5)::real score
 from public.x1_ai_knowledge k cross join q where k.is_published and (k.agent=p_agent or k.agent='both'))
 select r.id,r.slug,r.category,r.title,r.content,r.keywords,r.source_label,r.score from ranked r where r.score>0 order by r.score desc,r.updated_at desc limit least(greatest(coalesce(p_limit,8),1),12);
$$;
revoke all on function public.x1_search_ai_knowledge(text,text,integer) from public,anon,authenticated;
grant execute on function public.x1_search_ai_knowledge(text,text,integer) to service_role;
on conflict(agent,slug) do update set category=excluded.category,title=excluded.title,content=excluded.content,keywords=excluded.keywords,source_label=excluded.source_label,is_published=excluded.is_published,updated_at=now();
