insert into public.x1_ai_knowledge(agent,slug,category,title,content,keywords,source_label,is_published) values
('qureo','css-backgrounds','CSS','الخلفيات والصور في CSS','يمكن ضبط background-color وbackground-image وbackground-size وbackground-position وbackground-repeat. القيمة cover تملأ المساحة وقد تقص جزءاً من الصورة، بينما contain تعرض الصورة كاملة وقد تترك فراغاً. أضف لوناً احتياطياً وتأكد من وضوح النص فوق الخلفية.',array['background','image','cover','contain','خلفية'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','css-centering-layout','CSS','توسيط العناصر بطريقة صحيحة','لتوسيط عنصر داخل حاوية استخدم Flexbox مثل display:flex مع justify-content:center وalign-items:center، أو Grid مع place-items:center. للتوسيط الأفقي لعنصر block ذي عرض محدد يمكن استخدام margin-inline:auto. اختر الطريقة حسب بنية التخطيط ولا تعتمد على مسافات ثابتة عشوائية.',array['centering','justify-content','align-items','place-items','توسيط'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','css-custom-fonts','CSS','الخطوط وقراءة النص','تحدد font-family الخط مع قائمة بدائل، وتتحكم font-size وfont-weight وline-height وletter-spacing في القراءة. استخدم line-height مناسباً للنصوص الطويلة، وتأكد من دعم الخط للأحرف العربية. لا تعتمد على خط خارجي وحده؛ ضع بدائل نظامية.',array['font-family','font-size','font-weight','line-height','خطوط'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','css-fluid-sizing','CSS','الأحجام المرنة وclamp','تساعد وحدات rem و% وvw وmin وmax وclamp على إنشاء واجهات مرنة. clamp(min, preferred, max) تحدد قيمة لا تقل عن الحد الأدنى ولا تتجاوز الأعلى. مثال: font-size:clamp(1rem,2vw,1.5rem). اختبر على شاشة ضيقة وواسعة ولا تجعل النص صغيراً جداً.',array['clamp','min','max','rem','vw','responsive','أحجام'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','css-focus-visible','CSS','حالة focus-visible وإظهار التركيز','تظهر حالة :focus عندما يصل المستخدم إلى عنصر تفاعلي، ويمكن استخدام :focus-visible لإظهار مؤشر تركيز واضح خصوصاً عند استخدام لوحة المفاتيح. لا تزل outline دون بديل مرئي. يجب أن يستطيع المستخدم معرفة العنصر النشط أثناء التنقل بلوحة المفاتيح.',array['focus','focus-visible','outline','keyboard','تركيز'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','css-inheritance','CSS','الوراثة في CSS','بعض خصائص CSS مثل color وfont-family تنتقل غالباً من الأب إلى الأبناء، بينما خصائص مثل margin وborder لا تورث عادة. يمكن استخدام inherit أو initial أو unset للتحكم في القيمة. عند ظهور لون أو خط غير متوقع، افحص القاعدة الموروثة في أدوات المطور.',array['inheritance','inherit','initial','unset','وراثة'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','css-logical-properties','CSS','خصائص CSS المنطقية ودعم RTL','الخصائص المنطقية مثل margin-inline-start وpadding-block وinset-inline-end تتكيف مع اتجاه الكتابة RTL أو LTR بدلاً من ربط التصميم باليمين واليسار. هذا مفيد لواجهة عربية تدعم لغات متعددة. استخدمها عندما تريد أن يعمل التخطيط مع اتجاهات مختلفة.',array['rtl','ltr','logical properties','margin-inline','padding-block'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','css-overflow','CSS','التحكم في overflow','تحدد overflow ما يحدث عندما يتجاوز المحتوى مساحة العنصر. visible يسمح بظهوره، hidden يقص الزائد، auto يظهر التمرير عند الحاجة، وscroll يفرض منطقة تمرير. يمكن استخدام overflow-x وoverflow-y لكل محور. افحص ارتفاع العنصر وحجم المحتوى قبل إخفاء النص حتى لا تفقد معلومات مهمة.',array['overflow','hidden','auto','scroll','تمرير'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','css-pseudo-elements','CSS','العناصر الوهمية before وafter','تضيف ::before و::after محتوى زخرفياً قبل محتوى العنصر أو بعده، وغالباً تحتاج الخاصية content. استخدمها للزخرفة أو علامات العرض، لا للمعلومات الضرورية أو النص الذي يجب أن يصل لكل المستخدمين. افحص position وdisplay عند ترتيبها.',array['before','after','pseudo elements','content'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','css-transforms','CSS','Transform والتحويلات','تسمح transform بتحريك العنصر أو تدويره أو تكبيره أو إمالته دون تغيير تدفق العناصر المحيطة عادة. أمثلة translate وscale وrotate. يمكن ضبط transform-origin لنقطة التحويل. لا تستخدم التحويل لإخفاء مشكلة تخطيط أساسية؛ افحص Flexbox أو Grid أولاً.',array['transform','translate','scale','rotate','تحويل'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','css-transitions','CSS','Transitions والانتقالات','تجعل transition تغير الخاصية تدريجياً عند تغير قيمتها، مثل transition: transform .2s ease. حدد الخاصية والمدة ومنحنى الحركة، وتجنب الانتقال على جميع الخصائص بلا حاجة. احترم إعداد prefers-reduced-motion لتقليل الحركة لمن يفضل ذلك.',array['transition','animation','transform','ease','حركة'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','css-z-index','CSS','z-index وسياقات التكديس','تتحكم z-index في ترتيب العناصر المتراكبة داخل سياق التكديس. لا يكفي دائماً وضع رقم كبير؛ بعض الخصائص مثل transform وopacity وposition مع z-index قد تنشئ stacking context جديداً. افحص العنصر الأب والسياقات المحيطة قبل زيادة الرقم عشوائياً.',array['z-index','stacking context','layers','طبقات'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','html-audio-video','HTML','الصوت والفيديو في HTML','عنصر audio يعرض مشغلاً للصوت، وvideo يعرض الفيديو. يمكن إضافة controls لإظهار أدوات التشغيل، وsource لتحديد الملف ونوعه عبر type. أضف نصاً بديلاً أو ترجمة مكتوبة عندما يلزم، ولا تجعل التشغيل التلقائي المفاجئ هو السلوك الافتراضي. تأكد من حقوق استخدام الملفات ومن أن المسارات صحيحة.',array['audio','video','source','controls','وسائط'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','html-button-vs-link','HTML','متى تستخدم button ومتى تستخدم a','استخدم a عندما يكون الهدف الانتقال إلى عنوان أو صفحة أو موضع، وحدد href. استخدم button لتنفيذ فعل داخل الصفحة مثل إرسال نموذج أو فتح قائمة أو تغيير حالة. لا تستخدم div كزر دون سبب؛ العناصر الأصلية توفر سلوك لوحة المفاتيح وإمكانية الوصول تلقائياً.',array['button','a','href','link','زر','رابط'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','html-comments-entities','HTML','التعليقات والرموز الخاصة','تكتب تعليقات HTML بين <!-- و --> ولا تظهر للمستخدم في الصفحة، لكنها تبقى في مصدر الصفحة. بعض الرموز لها كيانات مثل &amp; لعلامة & و&lt; لعلامة أصغر و&gt; لعلامة أكبر و&nbsp; لمسافة غير قابلة للكسر. لا تستخدم التعليقات لتخزين كلمات مرور أو أسرار.',array['comments','entities','amp','lt','gt','تعليقات'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','html-data-attributes','HTML','الخصائص العامة وبيانات data','الخصائص مثل id وclass وtitle وlang تضيف معلومات أو تربط العنصر بالتنسيق والبرمجة. يجب أن تكون قيمة id فريدة داخل الصفحة، بينما يمكن تكرار class. خصائص data-* تخزن بيانات مخصصة مثل data-user-id ويمكن قراءتها عبر element.dataset. لا تضع أسراراً أو بيانات حساسة في خصائص HTML لأنها ظاهرة للمستخدم.',array['attributes','id','class','data attributes','dataset','خصائص'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','html-dom-tree','HTML','شجرة DOM والعناصر المتداخلة','يحوّل المتصفح HTML إلى شجرة عناصر تسمى DOM. العنصر الأب يحتوي أبناء، والعنصر الشقيق يشارك الأب نفسه. ترتيب العناصر والتداخل الصحيح مهمان؛ أغلق العناصر التي تتطلب إغلاقاً، ولا تضع عناصر block أو interactive داخل مواضع غير مسموحة. JavaScript تستطيع قراءة الشجرة وتعديلها عبر document.',array['DOM','tree','parent','child','شجرة العناصر'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','html-heading-hierarchy','HTML','ترتيب العناوين وبنية المحتوى','استخدم h1 للعنوان الرئيسي للصفحة، ثم h2 للأقسام وh3 للأقسام الفرعية حسب التسلسل المنطقي. لا تختَر مستوى العنوان لمجرد حجمه البصري؛ الحجم يضبطه CSS. وجود أكثر من عنوان رئيسي ليس دائماً خطأ، لكن البنية الواضحة تساعد القارئ وقارئات الشاشة ومحركات البحث. لا تتخطَّ المستويات بلا سبب.',array['heading','h1','h2','h3','العناوين','ترتيب العناوين'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','html-input-types','HTML','أنواع حقول input','تحدد type طريقة إدخال البيانات مثل text وemail وnumber وpassword وcheckbox وradio وdate. اختر النوع الذي يطابق البيانات، وأضف label واضحاً وname عند إرسال النموذج. خصائص required وmin وmax وminlength تساعد في التحقق داخل المتصفح، لكنها لا تغني عن التحقق الآمن على الخادم.',array['input','type','email','number','checkbox','radio','حقول'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','html-meta-viewport','HTML','Meta وViewport وإعداد الصفحة','داخل head توضع معلومات الصفحة. charset UTF-8 يدعم النصوص، وmeta name=viewport يساعد التصميم المتجاوب على استخدام عرض الجهاز، وtitle يحدد عنوان التبويب. يمكن إضافة description لوصف الصفحة. هذه العناصر لا تظهر عادة في محتوى body لكنها تؤثر في عرض الصفحة وفهمها.',array['meta','viewport','charset','title','description','head'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','js-array-methods','JavaScript','طرق المصفوفات الأساسية','push يضيف في النهاية، pop يحذف من النهاية، unshift يضيف في البداية، وshift يحذف من البداية. map ينشئ مصفوفة جديدة بتحويل كل عنصر، filter يختار عناصر تحقق شرطاً، find يعيد أول عنصر مطابق، وincludes يفحص وجود قيمة. اختر الطريقة التي تطابق المطلوب.',array['array','push','pop','shift','unshift','map','filter','find'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','js-array-sort','JavaScript','ترتيب المصفوفات sort','sort يرتب المصفوفة نفسها ويحوّل العناصر إلى نصوص افتراضياً. لترتيب الأرقام تصاعدياً استخدم (a,b)=>a-b، وللتنازلي (a,b)=>b-a. إذا أردت الحفاظ على الأصل انسخ المصفوفة أولاً باستخدام [...items]. انتبه إلى أن ترتيب النصوص قد يتأثر باللغة والحروف.',array['sort','compare function','arrays','ترتيب'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','js-classes','JavaScript','Classes وObjects','تستخدم class لتعريف قالب لإنشاء كائنات، وconstructor لتهيئة الخصائص، وnew لإنشاء instance. يمكن للدوال داخل class أن تمثل سلوك الكائن. افهم أولاً object وproperty وmethod قبل الانتقال إلى الوراثة؛ كثير من المهام البسيطة يمكن حلها بدوال وكائنات عادية.',array['class','constructor','new','instance','object'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','js-date','JavaScript','التعامل مع التاريخ Date','ينشئ new Date كائناً للتاريخ والوقت. getFullYear وgetMonth وgetDate تقرأ أجزاء التاريخ، لكن getMonth يبدأ من صفر. اعرض التاريخ بصيغة محلية عبر Intl.DateTimeFormat بدلاً من بناء صيغة يدوية غير مناسبة لكل اللغات.',array['Date','getMonth','Intl','DateTimeFormat'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','js-destructuring-spread','JavaScript','Destructuring وSpread وRest','يسمح destructuring باستخراج قيم من مصفوفة أو خصائص من كائن، مثل const {name}=user. عامل spread (...) ينسخ أو يدمج عناصر المصفوفة أو خصائص الكائن سطحياً. Rest يجمع بقية القيم في مصفوفة أو كائن أو معاملات دالة. النسخ سطحي وليس عميقاً.',array['destructuring','spread','rest','object','array'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','js-dom-create','JavaScript','إنشاء عناصر DOM وتعديلها','أنشئ عنصراً عبر document.createElement، ثم عدّل textContent أو classList، وبعدها أضفه عبر append أو appendChild. استخدم textContent للنص القادم من المستخدم بدلاً من innerHTML لتجنب تفسيره كـ HTML. احذف العنصر عبر remove عند الحاجة.',array['createElement','append','textContent','classList','DOM'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','js-equality-truthiness','JavaScript','المقارنة والقيم Truthy وFalsy','=== يقارن القيمة والنوع، بينما == قد يحول الأنواع قبل المقارنة. القيم falsy تشمل false و0 و-0 و0n والنص الفارغ وnull وundefined وNaN؛ ومعظم الكائنات والمصفوفات truthy حتى لو كانت فارغة. استخدم شروطاً واضحة وتجنب افتراض أن [] أو {} falsy.',array['strict equality','truthy','falsy','===','=='],'Seal X1 · QUREO local curriculum v2',true),
('qureo','js-event-bubbling','JavaScript','انتشار الأحداث Event Bubbling','عند وقوع حدث على عنصر قد ينتقل عبر العناصر الأب حتى document، وهذا يسمى bubbling. event.target هو العنصر الذي بدأ الحدث، وevent.currentTarget هو العنصر الذي رُبط عليه المستمع. stopPropagation يوقف الانتشار، واستخدمه فقط عند الحاجة.',array['event bubbling','target','currentTarget','stopPropagation'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','js-fetch','JavaScript','Fetch API وطلبات الشبكة','fetch يرسل طلباً ويعيد Promise. تحقق من response.ok لأن أخطاء HTTP مثل 404 لا ترفض Promise تلقائياً. بعد ذلك استخدم response.json أو response.text. عالج أخطاء الشبكة عبر try/catch، ولا تضع مفاتيح سرية في كود المتصفح.',array['fetch','response.ok','json','HTTP','network'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','js-form-validation','JavaScript','التحقق من النماذج','استمع إلى submit على form، واستخدم event.preventDefault عند الحاجة لمنع الإرسال الافتراضي، ثم افحص القيم. trim يزيل الفراغات من الأطراف، وcheckValidity يفحص قيود HTML. تحقق الخادم ضروري دائماً لأن فحص المتصفح يمكن تجاوزه.',array['form','submit','preventDefault','checkValidity','validation'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','js-local-storage','JavaScript','localStorage وsessionStorage','localStorage يخزن نصوصاً تستمر بين الجلسات عادة، وsessionStorage مرتبط بجلسة التبويب. استخدم setItem وgetItem وremoveItem، وحوّل الكائنات عبر JSON.stringify وJSON.parse. لا تخزن كلمات مرور أو أسراراً أو بيانات شديدة الحساسية فيهما.',array['localStorage','sessionStorage','setItem','getItem','JSON'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','js-map-set','JavaScript','Map وSet','Map يخزن أزواج مفتاح وقيمة ويمكن استخدام أنواع مختلفة كمفاتيح، وSet يخزن قيماً فريدة دون تكرار. استخدم map.set وmap.get وmap.has، واستخدم set.add وset.has وset.delete. هما مفيدان عندما لا تكون خصائص object أو المصفوفة هي الأنسب.',array['Map','Set','collections','has','get','add'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','js-modules','JavaScript','Modules وimport وexport','يسمح export بإتاحة دالة أو قيمة من ملف، وimport باستخدامها في ملف آخر. استخدم export default لقيمة افتراضية أو named exports لأكثر من عنصر. عند استخدام modules في المتصفح أضف type=module إلى script، وانتبه لمسارات الملفات وحالة الأحرف.',array['modules','import','export','type module'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','js-nullish-optional','JavaScript','Optional Chaining وNullish Coalescing','يوقف ?. الوصول إلى خاصية إذا كانت القيمة null أو undefined بدلاً من رمي خطأ. العامل ?? يستخدم قيمة بديلة فقط عندما تكون القيمة null أو undefined، بخلاف || الذي يستخدم البديل مع كل قيمة falsy مثل 0 أو النص الفارغ. اختر حسب المعنى المطلوب.',array['optional chaining','?.','nullish','??','fallback'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','js-number-math','JavaScript','الأرقام وMath والتحويل','استخدم Number لتحويل قيمة إلى رقم، وNumber.isNaN لفحص NaN، وMath.round للتقريب وMath.floor للنزول وMath.ceil للصعود وMath.max/Math.min للمقارنة. تذكر أن input.value نص حتى لو كان الحقل type=number؛ حوّله قبل العمليات الحسابية.',array['Number','Math','round','floor','ceil','isNaN'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','js-recursion','JavaScript','الدوال العودية Recursion','الدالة العودية تستدعي نفسها لحل نسخة أصغر من المشكلة. يجب وجود base case توقف الاستدعاء، وإلا قد يستمر حتى يحدث تجاوز للمكدس. تتبع قيمة المعامل في كل استدعاء، وقارن أحياناً الحل العودي بحلقة عندما يكون ذلك أوضح.',array['recursion','base case','call stack','عودية'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','js-scope-closures-practical','JavaScript','النطاق والإغلاق Closures','النطاق يحدد أين يمكن الوصول إلى المتغير. let وconst لهما block scope، بينما var له function scope. الإغلاق يحدث عندما تحتفظ دالة بإمكانية الوصول إلى متغيرات النطاق الذي أُنشئت فيه حتى بعد انتهاء الدالة الخارجية. استخدم هذا لفهم callbacks والحالة الخاصة.',array['scope','closure','let','const','var'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','js-string-methods','JavaScript','التعامل مع النصوص String','النصوص غير قابلة للتعديل في مكانها؛ الطرق مثل trim وtoLowerCase وtoUpperCase وincludes وstartsWith وslice وreplace تعيد نصاً جديداً. length تعطي عدد وحدات UTF-16 وليس بالضرورة عدد الرموز المرئية في كل اللغات. استخدم === للمقارنة الدقيقة غالباً.',array['string','trim','includes','slice','replace','length'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','js-template-literals','JavaScript','Template Literals والقوالب النصية','تستخدم العلامة الخلفية ` لكتابة نص متعدد الأسطر أو إدراج تعبير عبر ${expression}. مثال: const message = `Hello ${name}`. لا تخلط بين علامات الاقتباس العادية والقالب النصي؛ التعبير داخل ${} يُقيّم كـ JavaScript.',array['template literals','backticks','interpolation','strings'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','js-timers','JavaScript','setTimeout وsetInterval','setTimeout ينفذ callback مرة بعد مدة تقريبية، وsetInterval يكرر التنفيذ بفاصل زمني. clearTimeout وclearInterval يوقفان المؤقت. لا تفترض أن التوقيت دقيق تماماً؛ ازدحام الخيط الرئيسي أو تبويب الخلفية قد يؤخر التنفيذ.',array['setTimeout','setInterval','clearTimeout','timers'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','js-try-catch','JavaScript','معالجة الأخطاء try وcatch','استخدم try لتنفيذ عملية قد تفشل، وcatch لمعالجة الخطأ، ويمكن استخدام finally لتنفيذ خطوة أخيرة. في async/await ضع await داخل try إذا أردت التقاط رفض Promise. لا تبتلع الخطأ بصمت؛ اعرض رسالة مفهومة أو سجّل تفاصيل مناسبة للمطور دون كشف أسرار.',array['try','catch','finally','error','exception'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','qur-common-bugs','QUREO','أخطاء شائعة في تحديات البرمجة','راجع هذه النقاط عند فشل الحل: اسم متغير مختلف بحرف، استخدام = بدلاً من المقارنة، نسيان تحديث عداد الحلقة، شرط حدود خاطئ، أقواس أو علامات اقتباس غير مكتملة، خلط النص بالرقم، نسيان return، أو طباعة نص إضافي غير مطلوب. ارجع دائماً إلى صيغة السؤال.',array['common errors','syntax','assignment','return','أخطاء شائعة'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','qur-condition-order','QUREO','ترتيب الشروط ودمجها','في if وelse if يتم اختبار الشروط بالترتيب، وينفذ أول فرع يتحقق ثم يتجاوز بقية السلسلة. ضع الحالات الأكثر تحديداً قبل الحالات العامة عند تداخلها. استخدم && عندما يجب تحقق الشرطين، و|| عندما يكفي تحقق أحدهما، والأقواس لتوضيح الأولوية.',array['if','else if','&&','||','conditions'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','qur-debugging-process','QUREO','منهجية تشخيص خطأ البرمجة','ابدأ بقراءة نص الخطأ كاملاً، وحدد السطر أو الموضع المشار إليه، ثم افحص السطر وما قبله وبعده. قارن الناتج الفعلي بالمطلوب، وغيّر شيئاً واحداً في كل مرة. لا تستبدل الكود كله عشوائياً؛ كوّن فرضية واختبرها في بيئة QUREO أو المتصفح بنفسك.',array['debug','error message','خطأ','تشخيص','اختبار'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','qur-function-trace','QUREO','تتبع استدعاء الدالة وreturn','عند استدعاء دالة، طابق القيم المرسلة مع المعاملات، ثم تتبع جسم الدالة. return ينهي تنفيذ الدالة ويعيد القيمة إلى مكان الاستدعاء. console.log يعرض قيمة ولا يعيدها تلقائياً؛ لذلك لا تخلط بين الطباعة والإرجاع.',array['function','return','parameter','argument','console.log'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','qur-input-output','QUREO','فهم المدخلات والمخرجات','قبل كتابة الحل، حدد ما الذي يستقبله البرنامج وما النتيجة المطلوبة. جرّب مثالاً عادياً، وأصغر قيمة، وأكبر قيمة مسموحة، وحالة حدية مثل الصفر أو القائمة الفارغة إذا كانت مناسبة. لا تفترض تنسيق إدخال غير موجود في نص التحدي.',array['input','output','test cases','مدخلات','مخرجات'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','qur-loop-off-by-one','QUREO','أخطاء حدود الحلقات','من الأخطاء الشائعة اختيار شرط توقف يجعل الحلقة تنفذ مرة زائدة أو أقل. في for ابدأ بتحديد قيمة البداية، وشرط الاستمرار، وتحديث العداد. انتبه إلى الفرق بين i < n وi <= n، وإلى أن فهرسة المصفوفة تبدأ غالباً من صفر وتنتهي عند length-1.',array['loop','off by one','index','length','حدود'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','qur-pseudocode','QUREO','تحويل السؤال إلى خطوات شبه برمجية','حوّل المطلوب إلى خطوات قصيرة قبل كتابة الكود: اقرأ المدخلات، جهز المتغيرات، نفذ العمليات أو الشروط أو التكرار، ثم أخرج النتيجة. اكتب كل خطوة بلغة بسيطة، وبعدها اربطها بتعليمات اللغة التي تتعلمها. هذه الطريقة تقلل الأخطاء الناتجة عن البدء بالكود مباشرة.',array['pseudocode','algorithm','خوارزمية','خطوات'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','qur-test-cases','QUREO','اختيار حالات اختبار جيدة','لا تختبر الحل بمثال واحد فقط. اختر حالة نموذجية، وحالة صغيرة، وحالة حدية، وحالة تحقق الفرع الآخر من الشرط. إذا كان المطلوب جمع أرقام اختبر الصفر والقيم السالبة إن كانت مسموحة. إذا كان المطلوب مصفوفة اختبر عنصراً واحداً ومصفوفة فارغة إن كان ذلك ضمن المواصفات.',array['test cases','edge cases','اختبار','حالات حدية'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','qur-trace-variables','QUREO','تتبع قيم المتغيرات يدوياً','لتحليل برنامج، اكتب جدولاً بأسماء المتغيرات وقيمها الحالية. اقرأ التعليمات بالترتيب، وحدّث الجدول بعد كل عملية إسناد. عند الشرط قيّم التعبير إلى true أو false، وعند الحلقة كرر التتبع لكل دورة حتى يتحقق شرط التوقف. افصل بين قيمة المتغير قبل السطر وبعده.',array['trace','dry run','variables','تتبع','جدول'],'Seal X1 · QUREO local curriculum v2',true),
('qureo','qur-understand-prompt','QUREO','فهم صياغة التحدي قبل الحل','اقرأ المطلوب وحدد الأفعال المهمة مثل احسب أو اطبع أو أعد أو قارن. ميّز بين المطلوب كمدخل والمطلوب كمخرج، ولا تضف شروطاً غير مذكورة. إذا كان النص أو صورة التحدي غير واضحين، اطلب إعادة إرسال الجزء غير المقروء بدلاً من تخمين المطلوب.',array['prompt','challenge','requirements','تحدي','فهم السؤال'],'Seal X1 · QUREO local curriculum v2',true)
